const STRINGS: Record<Locale, Dict> = {
  en,
  'en-GB': enGB,
  'de-DE': de,
  ja,
  'fr-FR': fr,
  ko,
  'es-ES': es,
  'it-IT': it,
  'nl-NL': nl,
  sv,
  'pt-BR': ptBR,
};

/**
 * Read a translated field off a Supabase row with paired columns:
 *   <field>           — canonical (English) fallback
 *   <field>_en        — explicit English
 *   <field>_i18n      — jsonb {locale: text}
 * Picks current device locale > base-language match > English fallback.
 */
export function i18nField<T extends Record<string, any>>(
  row: T | null | undefined,
  field: 'title' | 'description',
): string {
  if (!row) return '';
  const locale = getLocale();
  const json = row[(field + '_i18n') as keyof T] as Record<string, string> | undefined | null;
  if (json && typeof json === 'object') {
    if (json[locale]) return json[locale];
    const base = locale.split('-')[0];
    const variant = Object.keys(json).find((k) => k === base || k.startsWith(base + '-'));
    if (variant && json[variant]) return json[variant];
  }
  const en = row[(field + '_en') as keyof T] as string | undefined;
  const fallback = row[field as keyof T] as string | undefined;
  return (en ?? fallback ?? '') as string;
}

export function t(key: string, params?: Record<string, string | number>): string {
  const locale = getLocale();
  const dict = STRINGS[locale] ?? STRINGS.en;
  let raw = dict[key] ?? STRINGS.en[key] ?? key;
  if (params) {
    for (const k of Object.keys(params)) {
      raw = raw.replace(new RegExp('\\{' + k + '\\}', 'g'), String(params[k]));
    }
  }
  return raw;
}
